 */
function readIntentPoint(intent) {
  const x = Number(intent?.x);
  const y = Number(intent?.y);
  if (!Number.isFinite(x) || !Number.isFinite(y)) return null;
  return { x: x | 0, y: y | 0 };
}

/**
