  });
}

function onItemDropped(world, ev = {}) {
  const actorId = normId(ev.actor);
  const itemId = normId(ev.itemId);
  if (!(actorId > 0) || !(itemId > 0)) return;
  const unpaid = world.get(itemId, Unpaid);
